What is the output of this Java code?
class R implements AutoCloseable {
  public void close() { System.out.print("C"); }
}
try (R r = new R()) {
  System.out.print("T");
  throw new RuntimeException();
} catch (RuntimeException e) { System.out.print("E"); }
finally { System.out.print("F"); }

